def compute(vars):
    total_obligations = vars["v2"]
    if total_obligations == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": None, "unit": "percentage"}}}

    ratio = vars["v1"] / total_obligations
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "ratio": ratio,
            "output_meta": {"currency": None, "scale": None, "unit": "percentage"}
        }
    }
